package dev.ledgerbank.gateway;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.core.convert.converter.Converter;import org.springframework.http.HttpCookie;import org.springframework.security.authentication.AbstractAuthenticationToken;import org.springframework.security.config.web.server.ServerHttpSecurity;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.*;import org.springframework.security.web.server.SecurityWebFilterChain;import reactor.core.publisher.Mono;
@Configuration class SecurityConfig{
 @Bean ReactiveJwtDecoder decoder(@Value("${ledgerbank.jwk-set-uri}")String uri){NimbusReactiveJwtDecoder decoder=NimbusReactiveJwtDecoder.withJwkSetUri(uri).build();decoder.setJwtValidator(validator(Set.of("ledgerbank-api")));return decoder;}
 @Bean SecurityWebFilterChain chain(ServerHttpSecurity h){Converter<Jwt,AbstractAuthenticationToken>base=j->{List<SimpleGrantedAuthority>a=new ArrayList<>();List<String>r=j.getClaimAsStringList("roles");if(r!=null)r.forEach(x->a.add(new SimpleGrantedAuthority("ROLE_"+x)));return new JwtAuthenticationToken(j,a,j.getSubject());};return h.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(a->a.pathMatchers("/actuator/health/**","/actuator/prometheus","/api/v1/auth/csrf","/api/v1/auth/register","/api/v1/auth/verify-email","/api/v1/auth/login","/api/v1/auth/refresh","/api/v1/auth/logout","/api/v1/auth/password-reset").permitAll().pathMatchers("/api/v1/auth/service-token","/api/v1/auth/.well-known/**").denyAll().pathMatchers("/api/v1/ops/**").hasRole("OPERATOR").pathMatchers("/api/v1/customers/**","/api/v1/kyc-submissions","/api/v1/accounts/**","/api/v1/transfers/**","/api/v1/external-accounts/**","/api/v1/ach-transfers/**").hasRole("CUSTOMER").anyExchange().authenticated()).oauth2ResourceServer(o->o.bearerTokenConverter(exchange->{HttpCookie cookie=exchange.getRequest().getCookies().getFirst("LB_ACCESS");return cookie==null?Mono.empty():Mono.just(new BearerTokenAuthenticationToken(cookie.getValue()));}).jwt(j->j.jwtAuthenticationConverter(new ReactiveJwtAuthenticationConverterAdapter(base)))).build();}
 private OAuth2TokenValidator<Jwt>validator(Set<String>audiences){OAuth2TokenValidator<Jwt>issuer=JwtValidators.createDefaultWithIssuer("ledgerbank-identity");OAuth2TokenValidator<Jwt>audience=jwt->jwt.getAudience().stream().anyMatch(audiences::contains)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Required audience is missing",null));return new DelegatingOAuth2TokenValidator<>(issuer,audience);}
}
